        var maxChar = 'a'
        var index = -1

        for (i in 0 until s.length) {
            val c = s[i]
            if (c == 'a') continue
            val prevChar = (c - 1).toChar()
            var canRemove = false

            if (i > 0 && s[i - 1] == prevChar) {
                canRemove = true
            }
            if (i < s.length - 1 && s[i + 1] == prevChar) {
                canRemove = true
            }

            if (canRemove) {
                if (c > maxChar) {
                    maxChar = c
                    index = i
                    found = true
                }
            }
        }

        if (!found) break

        s = s.removeRange(index, index + 1)
        count++
    }

    println(count)
}
