    while (queue.isNotEmpty()) {
        val current = queue.pollFirst()
        val currentLength = current.length
        maxRemovals = maxOf(maxRemovals, n - currentLength)
        for (i in 0 until currentLength) {
            val c = current[i]
            if (c == 'a') continue
            val prevChar = (c - 1).toChar()
            var canRemove = false
            if (i > 0 && current[i - 1] == prevChar) {
                canRemove = true
            }
            if (i < currentLength - 1 && current[i + 1] == prevChar) {
                canRemove = true
            }
            if (canRemove) {
                val newStr = current.removeRange(i, i + 1)
                if (!visited.contains(newStr)) {
                    visited.add(newStr)
                    queue.addLast(newStr)
                }
            }
        }
    }
